{"content":"1|//! Authoritative D-Bus sender-to-session identity binding.
2|//!
3|//! D-Bus does not traverse the gRPC interceptor. A caller therefore registers
4|//! its current, bus-assigned unique name with a SID1 sealed envelope (local)
5|//! or a fresh OIA1 proof (remote human) before it can use `PluginV1.Call`.
6|//! The registration never accepts a caller-selected principal, session,
7|//! sender, UID, GID, PID, or genesis value.
8|
9|use std::collections::HashMap;
10|use std::path::PathBuf;
11|use std::sync::Arc;
12|use std::sync::atomic::{AtomicBool, Ordering};
13|
14|use base64::Engine as _;
15|use futures::StreamExt as _;
16|use tokio::sync::{Mutex, RwLock};
17|use zbus::Connection;
18|use zbus::message::Header;
19|use zbus::names::BusName;
20|
21|use crate::interceptor::{GhostbridgeIdentity, load_capability_grants};
22|use crate::mutation_engine::MutationEngine;
23|use crate::oracle_assertion::AssertionValidator;
24|
25|pub const DBUS_IDENTITY_OBJECT_PATH: &str = "/org/opdbus/v1/identity/dbus";
26|pub const DBUS_IDENTITY_INTERFACE: &str = "org.opdbus.v1.DbusIdentityV1";
27|pub const DBUS_BIND_CAPABILITY: &str = "cap.identity.dbus.bind@v1";
28|const MAX_REGISTRATION_PROOF_BYTES: usize = 16 * 1024;
29|
30|#[derive(Debug, Clone, PartialEq, Eq)]
31|struct DbusPeerCredentials {
32|    uid: u32,
33|    effective_uid: u32,
34|    effective_gid: u32,
35|    group_ids: Vec<u32>,
36|    pid: u32,
37|    process_start_ticks: u64,
38|}
39|
40|#[derive(Debug, Clone)]
41|#[allow(dead_code)] // registered_at is stored for auditing but not yet read
42|struct DbusBinding {
43|    unique_name: String,
44|    peer: DbusPeerCredentials,
45|    principal_id: String,
46|    session_id: String,
47|    session_genesis: String,
48|    registered_at: i64,
49|}
50|
51|fn take_binding(
52|    bindings: &mut HashMap<String, DbusBinding>,
53|    sender: &str,
54|) -> Option<(DbusBinding, bool)> {
55|    let removed = bindings.remove(sender)?;
56|    let last_for_session = !bindings
57|        .values()
58|        .any(|binding| binding.session_id == removed.session_id);
59|    Some((removed, last_for_session))
60|}
61|
62|#[derive(Debug, thiserror::Error)]
63|pub enum DbusIdentityError {
64|    #[error("D-Bus caller has no unique sender")]
65|    NoSender,
66|    #[error("D-Bus sender-exit monitor is unavailable")]
67|    MonitorUnavailable,
68|    #[error("D-Bus peer credentials are unavailable")]
69|    PeerCredentialsUnavailable,
70|    #[error("D-Bus caller has no registered identity binding")]
71|    NoBinding,
72|    #[error("D-Bus caller binding is stale")]
73|    StaleBinding,
74|    #[error("D-Bus registration proof was rejected")]
75|    RegistrationProofRejected,
76|    #[error("D-Bus registration capability was denied")]
77|    CapabilityDenied,
78|    #[error("D-Bus authoritative session is unavailable")]
79|    SessionUnavailable,
80|}
81|
82|/// Resolves a bus-owned unique sender through immutable peer credentials and
83|/// an already-authenticated, still-current human session.
84|pub struct DbusIdentityResolver {
85|    connection: Connection,
86|    bindings: RwLock<HashMap<String, DbusBinding>>,
87|    engine: Arc<MutationEngine>,
88|    validator: Arc<AssertionValidator>,
89|    monitor_live: AtomicBool,
90|    /// Serializes first-binding activation with last-binding parking.
91|    lifecycle_transition: Mutex<()>,
92|}
93|
94|impl DbusIdentityResolver {
95|    pub fn new(
96|        connection: Connection,
97|        engine: Arc<MutationEngine>,
98|        validator: Arc<AssertionValidator>,
99|    ) -> Arc<Self> {
100|        Arc::new(Self {
101|            connection,
102|            bindings: RwLock::new(HashMap::new()),
103|            engine,
104|            validator,
105|            monitor_live: AtomicBool::new(false),
106|            lifecycle_transition: Mutex::new(()),
107|        })
108|    }
109|
110|    /// Subscribe before exposing the registration object. If the subscription
111|    /// ever ends, every binding is discarded and resolution fails closed.
112|    pub async fn start_exit_monitor(self: &Arc<Self>) -> anyhow::Result<()> {
113|        let resolver = Arc::clone(self);
114|        let connection = self.connection.clone();
115|        let (ready_tx, ready_rx) = tokio::sync::oneshot::channel::<Result<(), String>>();
116|
117|        tokio::spawn(async move {
118|            let proxy = match zbus::fdo::DBusProxy::new(&connection).await {
119|                Ok(proxy) => proxy,
120|                Err(error) => {
121|                    let _ = ready_tx.send(Err(error.to_string()));
122|                    return;
123|                }
124|            };
125|            let mut stream = match proxy.receive_name_owner_changed().await {
126|                Ok(stream) => stream,
127|                Err(error) => {
128|                    let _ = ready_tx.send(Err(error.to_string()));
129|                    return;
130|                }
131|            };
132|
133|            resolver.monitor_live.store(true, Ordering::Release);
134|            let _ = ready_tx.send(Ok(()));
135|
136|            while let Some(signal) = stream.next().await {
137|                let Ok(args) = signal.args() else {
138|                    continue;
139|                };
140|                if args.new_owner().as_ref().is_none()
141|                    && let Err(error) = resolver.revoke_sender(args.name().as_str()).await
142|                {
143|                    tracing::error!(%error, sender = args.name().as_str(), "failed to park disconnected D-Bus identity session");
144|                }
145|            }
146|
147|            resolver.monitor_live.store(false, Ordering::Release);
148|            if let Err(error) = resolver.revoke_all_senders().await {
149|                tracing::error!(%error, "failed to park all sessions after D-Bus monitor exit");
150|            }
151|            tracing::error!("D-Bus NameOwnerChanged stream ended; identity bindings disabled");
152|        });
153|
154|        match ready_rx.await {
155|            Ok(Ok(())) => Ok(()),
156|            Ok(Err(error)) => anyhow::bail!("subscribe to D-Bus NameOwnerChanged: {error}"),
157|            Err(_) => anyhow::bail!("D-Bus NameOwnerChanged monitor stopped during startup"),
158|        }
159|    }
160|
161|    /// Bind only the sender named by this message header. The opaque proof is
162|    /// a SID1 sealed envelope or a fresh OIA1 envelope; all identity/session
163|    /// values are resolved by the existing validator and MutationEngine.
164|    pub async fn register_current_sender(
165|        &self,
166|        header: &Header<'_>,
167|        registration_proof: &[u8],
168|    ) -> Result<GhostbridgeIdentity, DbusIdentityError> {
169|        if !self.monitor_live.load(Ordering::Acquire) {
170|            return Err(DbusIdentityError::MonitorUnavailable);
171|        }
172|        if registration_proof.is_empty() || registration_proof.len() > MAX_REGISTRATION_PROOF_BYTES
173|        {
174|            return Err(DbusIdentityError::RegistrationProofRejected);
175|        }
176|        if registration_proof.starts_with(b"SID1") {
177|            return self
178|                .register_current_sender_sid1(header, registration_proof)
179|                .await;
180|        }
181|
182|        let sender = sender_from_header(header)?;
183|        let initial_peer = self.read_peer_credentials(&sender).await?;
184|        let now = chrono::Utc::now().timestamp();
185|        let mut pending = self
186|            .validator
187|            .validate_pending_with_bootstrap(registration_proof, None, now, false)
188|            .map_err(|error| {
189|                tracing::warn!(%error, sender, "D-Bus registration OIA rejected");
190|                DbusIdentityError::RegistrationProofRejected
191|            })?;
192|
193|        let session = self
194|            .verified_session_for_activation(&pending.identity().human_pubkey)
195|            .await?
196|            .ok_or(DbusIdentityError::SessionUnavailable)?;
197|        pending.identity_mut().session_id = session.session_id.clone();
198|        pending.identity_mut().session_genesis = session.genesis_hex.clone();
199|
200|        if !load_capability_grants(&pending.identity().principal_id).contains(DBUS_BIND_CAPABILITY)
201|        {
202|            return Err(DbusIdentityError::CapabilityDenied);
203|        }
204|
205|        self.authoritative_identity(&pending.identity().principal_id, &session.session_id, false)
206|            .await?;
207|
208|        // Re-read credentials after proof validation so a disconnect or
209|        // process replacement during registration cannot inherit the proof.
210|        let current_peer = self.read_peer_credentials(&sender).await?;
211|        if current_peer != initial_peer {
212|            return Err(DbusIdentityError::StaleBinding);
213|        }
214|
215|        let identity = self.validator.consume_pending(pending).map_err(|error| {
216|            tracing::warn!(%error, sender, "D-Bus registration OIA replay rejected");
217|            DbusIdentityError::RegistrationProofRejected
218|        })?;
219|        // Serialize binding insertion with disconnect/logout. The first
220|        // authenticated binding activates (and starts) the parked container;
221|        // additional bindings share that live term without a second start.
222|        let _transition = self.lifecycle_transition.lock().await;
223|        {
224|            let bindings = self.bindings.read().await;
225|            if bindings
226|                .get(&sender)
227|                .is_some_and(|binding| binding.session_id != identity.session_id)
228|            {
229|                return Err(DbusIdentityError::StaleBinding);
230|            }
231|        }
232|        let first_binding = !self
233|            .bindings
234|            .read()
235|            .await
236|            .values()
237|            .any(|binding| binding.session_id == identity.session_id);
238|        crate::identity_sled_dispatch::activate_session(
239|            self.engine.as_ref(),
240|            &identity.session_id,
241|        )
242|        .await
243|        .map_err(|error| {
244|            tracing::error!(%error, session_id = %identity.session_id, "authenticated session activation failed");
245|            DbusIdentityError::SessionUnavailable
246|        })?;
247|        let resolved = match self
248|            .authoritative_identity(&identity.principal_id, &identity.session_id, true)
249|            .await
250|        {
251|            Ok(resolved) => resolved,
252|            Err(error) => {
253|                if first_binding {
254|                    let _ = crate::identity_sled_dispatch::deactivate_session(
255|                        self.engine.as_ref(),
256|                        &identity.session_id,
257|                    )
258|                    .await;
259|                }
260|                return Err(error);
261|            }
262|        };
263|
264|        self.bindings.write().await.insert(
265|            sender.clone(),
266|            DbusBinding {
267|                unique_name: sender.clone(),
268|                peer: current_peer.clone(),
269|                principal_id: resolved.principal_id.clone(),
270|                session_id: resolved.session_id.clone(),
271|                session_genesis: resolved.session_genesis.clone(),
272|                registered_at: now,
273|            },
274|        );
275|        drop(_transition);
276|
277|        // Close the final insert race: if the sender vanished between the
278|        // second credential read and insertion, remove the just-added entry.
279|        if !matches!(
280|            self.read_peer_credentials(&sender).await,
281|            Ok(peer) if peer == current_peer
282|        ) {
283|            if let Err(error) = self.revoke_sender(&sender).await {
284|                tracing::error!(%error, sender, "failed to park stale D-Bus identity session");
285|            }
286|            return Err(DbusIdentityError::StaleBinding);
287|        }
288|
289|        // Publish the in-memory context only after proof consumption,
290|        // activation, authoritative resolution, binding insertion, and the
291|        // final peer-credential race check have all succeeded.
292|        self.engine
293|            .register_session_context(crate::mutation_engine::SessionContext {
294|                genesis_hex: resolved.session_genesis.clone(),
295|                session_id: resolved.session_id.clone(),
296|                wireguard_pubkey: session.wireguard_pubkey,
297|                sealed_id_digest: crate::identity_sled_dispatch::stored_session(
298|                    self.engine.as_ref(),
299|                    &resolved.session_id,
300|                )
301|                .await
302|                .ok()
303|                .flatten()
304|                .and_then(|sled| {
305|                    crate::mutation_engine::sealed_id_digest(sled.sealed_id.as_deref())
306|                }),
307|            })
308|            .await;
309|
310|        tracing::info!(
311|            sender,
312|            principal_id = %resolved.principal_id,
313|            session_id = %resolved.session_id,
314|            "registered current D-Bus sender identity"
315|        );
316|        Ok(resolved)
317|    }
318|
319|    async fn register_current_sender_sid1(
320|        &self,
321|        header: &Header<'_>,
322|        registration_proof: &[u8],
323|    ) -> Result<GhostbridgeIdentity, DbusIdentityError> {
324|        let sender = sender_from_header(header)?;
325|        let initial_peer = self.read_peer_credentials(&sender).await?;
326|        let now = chrono::Utc::now().timestamp();
327|        let claims = crate::identity_sled_dispatch::authenticate_sid1_wire(
328|            self.engine.as_ref(),
329|            registration_proof,
330|            "dbus",
331|        )
332|        .await
333|        .map_err(|error| {
334|            tracing::warn!(%error, sender, "D-Bus registration SID1 rejected");
335|            DbusIdentityError::RegistrationProofRejected
336|        })?;
337|
338|        if !load_capability_grants(&claims.principal_id).contains(DBUS_BIND_CAPABILITY) {
339|            return Err(DbusIdentityError::CapabilityDenied);
340|        }
341|
342|        self.authoritative_identity(&claims.principal_id, &claims.session_id, false)
343|            .await?;
344|
345|        let current_peer = self.read_peer_credentials(&sender).await?;
346|        if current_peer != initial_peer {
347|            return Err(DbusIdentityError::StaleBinding);
348|        }
349|
350|        let _transition = self.lifecycle_transition.lock().await;
351|        {
352|            let bindings = self.bindings.read().await;
353|            if bindings
354|                .get(&sender)
355|                .is_some_and(|binding| binding.session_id != claims.session_id)
356|            {
357|                return Err(DbusIdentityError::StaleBinding);
358|            }
359|        }
360|        let first_binding = !self
361|            .bindings
362|            .read()
363|            .await
364|            .values()
365|            .any(|binding| binding.session_id == claims.session_id);
366|        crate::identity_sled_dispatch::activate_session(self.engine.as_ref(), &claims.session_id)
367|            .await
368|            .map_err(|error| {
369|                tracing::error!(%error, session_id = %claims.session_id, "authenticated session activation failed");
370|                DbusIdentityError::SessionUnavailable
371|            })?;
372|        let resolved = match self
373|            .authoritative_identity(&claims.principal_id, &claims.session_id, true)
374|            .await
375|        {
376|            Ok(resolved) => resolved,
377|            Err(error) => {
378|                if first_binding {
379|                    let _ = crate::identity_sled_dispatch::deactivate_session(
380|                        self.engine.as_ref(),
381|                        &claims.session_id,
382|                    )
383|                    .await;
384|                }
385|                return Err(error);
386|            }
387|        };
388|
389|        self.bindings.write().await.insert(
390|            sender.clone(),
391|            DbusBinding {
392|                unique_name: sender.clone(),
393|                peer: current_peer.clone(),
394|                principal_id: resolved.principal_id.clone(),
395|                session_id: resolved.session_id.clone(),
396|                session_genesis: resolved.session_genesis.clone(),
397|                registered_at: now,
398|            },
399|        );
400|        drop(_transition);
401|
402|        if !matches!(
403|            self.read_peer_credentials(&sender).await,
404|            Ok(peer) if peer == current_peer
405|        ) {
406|            if let Err(error) = self.revoke_sender(&sender).await {
407|                tracing::error!(%error, sender, "failed to park stale D-Bus identity session");
408|            }
409|            return Err(DbusIdentityError::StaleBinding);
410|        }
411|
412|        self.engine
413|            .register_session_context(crate::mutation_engine::SessionContext {
414|                genesis_hex: resolved.session_genesis.clone(),
415|                session_id: resolved.session_id.clone(),
416|                wireguard_pubkey: claims.wireguard_pubkey,
417|                sealed_id_digest: crate::identity_sled_dispatch::stored_session(
418|                    self.engine.as_ref(),
419|                    &resolved.session_id,
420|                )
421|                .await
422|                .ok()
423|                .flatten()
424|                .and_then(|sled| {
425|                    crate::mutation_engine::sealed_id_digest(sled.sealed_id.as_deref())
426|                }),
427|            })
428|            .await;
429|
430|        tracing::info!(
431|            sender,
432|            principal_id = %resolved.principal_id,
433|            session_id = %resolved.session_id,
434|            "registered current D-Bus sender identity from SID1"
435|        );
436|        Ok(resolved)
437|    }
438|
439|    /// Resolve and revalidate the binding for the current message sender.
440|    pub async fn resolve(
441|        &self,
442|        header: &Header<'_>,
443|    ) -> Result<GhostbridgeIdentity, DbusIdentityError> {
444|        if !self.monitor_live.load(Ordering::Acquire) {
445|            return Err(DbusIdentityError::MonitorUnavailable);
446|        }
447|        let sender = sender_from_header(header)?;
448|        let binding = self
449|            .bindings
450|            .read()
451|            .await
452|            .get(&sender)
453|            .cloned()
454|            .ok_or(DbusIdentityError::NoBinding)?;
455|
456|        let peer = match self.read_peer_credentials(&sender).await {
457|            Ok(peer) if peer == binding.peer => peer,
458|            _ => {
459|                let _ = self.revoke_sender(&sender).await;
460|                return Err(DbusIdentityError::StaleBinding);
461|            }
462|        };
463|        if peer.process_start_ticks != binding.peer.process_start_ticks
464|            || binding.unique_name != sender
465|        {
466|            let _ = self.revoke_sender(&sender).await;
467|            return Err(DbusIdentityError::StaleBinding);
468|        }
469|
470|        let identity = match self
471|            .authoritative_identity(&binding.principal_id, &binding.session_id, true)
472|            .await
473|        {
474|            Ok(identity) if identity.session_genesis == binding.session_genesis => identity,
475|            _ => {
476|                let _ = self.revoke_sender(&sender).await;
477|                return Err(DbusIdentityError::SessionUnavailable);
478|            }
479|        };
480|        Ok(identity)
481|    }
482|
483|    /// Revoke only the bus-assigned current sender named by the caller header.
484|    pub async fn logout_current_sender(
485|        &self,
486|        header: &Header<'_>,
487|    ) -> Result<bool, DbusIdentityError> {
488|        let sender = sender_from_header(header)?;
489|        self.revoke_sender(&sender).await
490|    }
491|
492|    async fn revoke_sender(&self, sender: &str) -> Result<bool, DbusIdentityError> {
493|        let _transition = self.lifecycle_transition.lock().await;
494|        let removed = {
495|            let mut bindings = self.bindings.write().await;
496|            take_binding(&mut bindings, sender)
497|        };
498|        let Some((removed, last_binding)) = removed else {
499|            return Ok(false);
500|        };
501|        if last_binding {
502|            let parking = crate::identity_sled_dispatch::deactivate_session(
503|                self.engine.as_ref(),
504|                &removed.session_id,
505|            )
506|            .await;
507|            self.engine
508|                .forget_session_context(&removed.session_id)
509|                .await;
510|            parking.map_err(|error| {
511|                tracing::error!(%error, session_id = %removed.session_id, "identity container parking failed");
512|                DbusIdentityError::SessionUnavailable
513|            })?;
514|        }
515|        tracing::info!(sender, session_id = %removed.session_id, last_binding, "revoked D-Bus sender identity binding");
516|        Ok(true)
517|    }
518|
519|    async fn revoke_all_senders(&self) -> Result<(), DbusIdentityError> {
520|        let _transition = self.lifecycle_transition.lock().await;
521|        let sessions: std::collections::HashSet<String> = self
522|            .bindings
523|            .write()
524|            .await
525|            .drain()
526|            .map(|(_, binding)| binding.session_id)
527|            .collect();
528|        let mut failed = false;
529|        for session_id in sessions {
530|            if let Err(error) =
531|                crate::identity_sled_dispatch::deactivate_session(self.engine.as_ref(), &session_id)
532|                    .await
533|            {
534|                failed = true;
535|                tracing::error!(%error, %session_id, "identity container parking failed during binding drain");
536|            }
537|            self.engine.forget_session_context(&session_id).await;
538|        }
539|        if failed {
540|            Err(DbusIdentityError::SessionUnavailable)
541|        } else {
542|            Ok(())
543|        }
544|    }
545|
546|    async fn read_peer_credentials(
547|        &self,
548|        sender: &str,
549|    ) -> Result<DbusPeerCredentials, DbusIdentityError> {
550|        let proxy = zbus::fdo::DBusProxy::new(&self.connection)
551|            .await
552|            .map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
553|        let bus_name =
554|            BusName::try_from(sender).map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
555|        let credentials = proxy
556|            .get_connection_credentials(bus_name)
557|            .await
558|            .map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
559|        let uid = credentials
560|            .unix_user_id()
561|            .ok_or(DbusIdentityError::PeerCredentialsUnavailable)?;
562|        let pid = credentials
563|            .process_id()
564|            .filter(|pid| *pid != 0)
565|            .ok_or(DbusIdentityError::PeerCredentialsUnavailable)?;
566|        let mut group_ids = credentials
567|            .unix_group_ids()
568|            .cloned()
569|            .filter(|groups| !groups.is_empty())
570|            .ok_or(DbusIdentityError::PeerCredentialsUnavailable)?;
571|        group_ids.sort_unstable();
572|        group_ids.dedup();
573|
574|        let first_start = read_process_start_ticks(pid)
575|            .map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
576|        let (effective_uid, effective_gid) =
577|            read_effective_ids(pid).map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
578|        let process_start_ticks = read_process_start_ticks(pid)
579|            .map_err(|_| DbusIdentityError::PeerCredentialsUnavailable)?;
580|        if first_start != process_start_ticks
581|            || effective_uid != uid
582|            || !group_ids.contains(&effective_gid)
583|        {
584|            return Err(DbusIdentityError::PeerCredentialsUnavailable);
585|        }
586|
587|        Ok(DbusPeerCredentials {
588|            uid,
589|            effective_uid,
590|            effective_gid,
591|            group_ids,
592|            pid,
593|            process_start_ticks,
594|        })
595|    }
596|
597|    /// Resolve a verified login against an existing sled without requiring
598|    /// that sled to already be active. This is the sole parked-session
599|    /// exception: the fresh OIA proof and principal checks precede it, and
600|    /// registration immediately activates the exact server-derived session.
601|    async fn verified_session_for_activation(
602|        &self,
603|        wireguard_pubkey: &str,
604|    ) -> Result<Option<crate::mutation_engine::SessionContext>, DbusIdentityError> {
605|        let valid_wireguard_key = base64::engine::general_purpose::STANDARD
606|            .decode(wireguard_pubkey.trim())
607|            .is_ok_and(|raw| raw.len() == 32);
608|        if !valid_wireguard_key {
609|            return Ok(None);
610|        }
611|        let session_id = op_identity::session::derive_session_id(wireguard_pubkey);
612|        if let Some(record) = crate::identity_sled_dispatch::stored_session(
613|            self.engine.as_ref(),
614|            &session_id,
615|        )
616|        .await
617|        .map_err(|error| {
618|            tracing::error!(%error, %session_id, "identity credential projection unavailable");
619|            DbusIdentityError::SessionUnavailable
620|        })? {
621|            let now = chrono::Utc::now().timestamp();
622|            if !record.is_anchored()
623|                || record.wireguard_pubkey != wireguard_pubkey
624|                || !record
625|                    .expires_at
626|                    .is_none_or(|expires_at| expires_at == 0 || expires_at > now)
627|            {
628|                return Ok(None);
629|            }
630|            let context = crate::mutation_engine::SessionContext {
631|                genesis_hex: record.genesis.unwrap_or_default(),
632|                sealed_id_digest: crate::mutation_engine::sealed_id_digest(
633|                    record.sealed_id.as_deref(),
634|                ),
635|                session_id: record.session_id,
636|                wireguard_pubkey: record.wireguard_pubkey,
637|            };
638|            return Ok(Some(context));
639|        }
640|        // D-Bus login activates an already provisioned/authored sled. Minting
641|        // here would cache a SessionContext before nonce consumption and the
642|        // final peer-credential check; provisioning/arrival owns that step.
643|        Ok(None)
644|    }
