646|    async fn authoritative_identity(
647|        &self,
648|        expected_principal: &str,
649|        session_id: &str,
650|        require_active: bool,
651|    ) -> Result<GhostbridgeIdentity, DbusIdentityError> {
652|        authoritative_session_identity(
653|            self.engine.as_ref(),
654|            Some(expected_principal),
655|            session_id,
656|            require_active,
657|        )
658|        .await
659|    }
