662|/// Resolve a session to its registered principal from the committed sled
663|/// projection and the key registry alone. The session must be anchored,
664|/// unexpired and, when `require_active`, active; its WireGuard key must map
665|/// to an unrevoked principal, which must equal `expected_principal` when one
666|/// is given. Nothing here trusts a caller-supplied principal or genesis.
667|pub(crate) async fn authoritative_session_identity(
668|    engine: &MutationEngine,
669|    expected_principal: Option<&str>,
670|    session_id: &str,
671|    require_active: bool,
672|) -> Result<GhostbridgeIdentity, DbusIdentityError> {
673|    let session = crate::identity_sled_dispatch::stored_session(engine, session_id)
674|        .await
675|        .map_err(|error| {
676|            tracing::error!(%error, %session_id, "identity credential projection unavailable");
677|            DbusIdentityError::SessionUnavailable
678|        })?
679|        .filter(|session| session.is_anchored())
680|        .filter(|session| !require_active || session.active)
681|        .filter(|session| {
682|            session
683|                .expires_at
684|                .is_none_or(|expires| expires == 0 || expires > chrono::Utc::now().timestamp())
685|        })
686|        .ok_or(DbusIdentityError::SessionUnavailable)?;
687|    let session_genesis = session
688|        .genesis
689|        .filter(|genesis| !genesis.is_empty())
690|        .ok_or(DbusIdentityError::SessionUnavailable)?;
691|    if session.wireguard_pubkey.is_empty() {
692|        return Err(DbusIdentityError::SessionUnavailable);
693|    }
694|
695|    let principal =
696|        crate::human_principal_dispatch::resolve_key_for_assertion(&session.wireguard_pubkey)
697|            .await
698|            .map_err(|_| DbusIdentityError::SessionUnavailable)?
699|            .filter(|record| record.revoked_at == 0)
700|            .filter(|record| {
701|                expected_principal.is_none_or(|expected| record.principal_id == expected)
702|            })
703|            .ok_or(DbusIdentityError::SessionUnavailable)?;
704|
705|    Ok(GhostbridgeIdentity {
706|        principal_id: principal.principal_id,
707|        session_id: session.session_id,
708|        session_genesis,
709|    })
710|}
