762|fn read_process_start_ticks(pid: u32) -> std::io::Result<u64> {
763|    let stat = std::fs::read_to_string(proc_path(pid, "stat"))?;
764|    parse_process_start_ticks(&stat)
765|        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, "invalid proc stat"))
766|}
