768|fn parse_process_start_ticks(stat: &str) -> Option<u64> {
769|    let (_, fields) = stat.rsplit_once(") ")?;
770|    // The suffix starts at field 3 (`state`); process start time is field 22.
771|    fields.split_whitespace().nth(19)?.parse().ok()
772|}
773|
774|fn read_effective_ids(pid: u32) -> std::io::Result<(u32, u32)> {
775|    let status = std::fs::read_to_string(proc_path(pid, "status"))?;
776|    let effective = |label: &str| -> Option<u32> {
777|        status
778|            .lines()
779|            .find_map(|line| line.strip_prefix(label))?
780|            .split_whitespace()
781|            .nth(1)?
782|            .parse()
783|            .ok()
784|    };
785|    match (effective("Uid:"), effective("Gid:")) {
786|        (Some(uid), Some(gid)) => Ok((uid, gid)),
787|        _ => Err(std::io::Error::new(
788|            std::io::ErrorKind::InvalidData,
789|            "effective IDs absent from proc status",
790|        )),
791|    }
