32|/// This fd refers to the socket's original peer, even after its numeric PID is
33|/// recycled. Opening a pidfd by that numeric PID would already be too late.
34|struct PeerLifetime(OwnedFd);
35|
36|impl PeerLifetime {
37|    fn from_socket(socket: &impl AsRawFd) -> Result<Self> {
38|        let mut fd: libc::c_int = -1;
39|        let mut length = std::mem::size_of_val(&fd) as libc::socklen_t;
40|        // SAFETY: both output pointers refer to live, correctly sized values;
41|        // the borrowed socket remains open throughout this call.
42|        let result = unsafe {
43|            libc::getsockopt(
44|                socket.as_raw_fd(),
45|                libc::SOL_SOCKET,
46|                libc::SO_PEERPIDFD,
47|                (&mut fd as *mut libc::c_int).cast(),
48|                &mut length,
49|            )
50|        };
51|        if result != 0 {
52|            return Err(std::io::Error::last_os_error())
53|                .context("socket peer lifetime unavailable");
54|        }
55|        ensure!(fd >= 0, "socket peer lifetime unavailable");
56|        // SAFETY: successful SO_PEERPIDFD returns a new owned, close-on-exec fd.
57|        let lifetime = Self(unsafe { OwnedFd::from_raw_fd(fd) });
58|        ensure!(
59|            length as usize == std::mem::size_of_val(&fd),
60|            "invalid socket peer lifetime"
61|        );
62|        lifetime.ensure_alive()?;
63|        Ok(lifetime)
64|    }
65|
66|    fn ensure_alive(&self) -> Result<()> {
67|        let mut descriptor = libc::pollfd {
68|            fd: self.0.as_raw_fd(),
69|            events: libc::POLLIN,
70|            revents: 0,
71|        };
72|        // SAFETY: descriptor is a live pollfd; timeout zero cannot block.
73|        let result = unsafe { libc::poll(&mut descriptor, 1, 0) };
74|        if result < 0 {
75|            return Err(std::io::Error::last_os_error())
76|                .context("socket peer lifetime unavailable");
77|        }
78|        ensure!(result == 0 && descriptor.revents == 0, "socket peer exited");
79|        Ok(())
80|    }
81|
82|    fn read_process(&self, pid: u32) -> Result<ProcessIdentity> {
83|        self.ensure_alive()?;
84|        let process = ProcessIdentity::read(pid)?;
85|        self.ensure_alive()?;
86|        Ok(process)
87|    }
88|
89|    fn revalidate(&self, process: &ProcessIdentity) -> Result<()> {
90|        self.ensure_alive()?;
91|        process.revalidate()?;
92|        self.ensure_alive()
93|    }
94|}
