96|/// Holding the namespace open prevents its inode being recycled while bound.
97|#[derive(Clone, Debug)]
98|struct NamespaceIdentity {
99|    dev: u64,
100|    ino: u64,
101|    _handle: Arc<File>,
102|}
103|
104|impl PartialEq for NamespaceIdentity {
105|    fn eq(&self, other: &Self) -> bool {
106|        self.dev == other.dev && self.ino == other.ino
107|    }
108|}
109|impl Eq for NamespaceIdentity {}
110|
111|#[derive(Clone, Debug, PartialEq, Eq)]
112|struct ProcessIdentity {
113|    pid: u32,
114|    start_ticks: u64,
115|    user_namespace: NamespaceIdentity,
116|    pid_namespace: NamespaceIdentity,
117|}
118|
119|impl ProcessIdentity {
120|    fn read(pid: u32) -> Result<Self> {
121|        ensure!(pid > 0, "peer process is unavailable");
122|        let start_ticks = read_start_ticks(pid)?;
123|        let namespace = |name| -> Result<NamespaceIdentity> {
124|            let handle = File::open(format!("/proc/{pid}/ns/{name}"))?;
125|            let metadata = handle.metadata()?;
126|            Ok(NamespaceIdentity {
127|                dev: metadata.dev(),
128|                ino: metadata.ino(),
129|                _handle: Arc::new(handle),
130|            })
131|        };
132|        let identity = Self {
133|            pid,
134|            start_ticks,
135|            user_namespace: namespace("user")?,
136|            pid_namespace: namespace("pid")?,
137|        };
138|        ensure!(
139|            read_start_ticks(pid)? == start_ticks,
140|            "peer process changed"
141|        );
142|        Ok(identity)
143|    }
144|
145|    fn same_namespaces(&self, other: &Self) -> bool {
146|        self.user_namespace == other.user_namespace && self.pid_namespace == other.pid_namespace
147|    }
148|
149|    fn revalidate(&self) -> Result<()> {
150|        ensure!(Self::read(self.pid)? == *self, "peer process changed");
151|        Ok(())
152|    }
153|}
154|
155|fn read_start_ticks(pid: u32) -> Result<u64> {
156|    let stat = std::fs::read_to_string(format!("/proc/{pid}/stat"))?;
157|    // The process name can contain spaces and ')'. Fields after its final
158|    // closing ')' start at field 3; field 22 is the process start time.
159|    parse_start_ticks(&stat).context("invalid process identity")
160|}
161|
162|fn parse_start_ticks(stat: &str) -> Option<u64> {
163|    stat.rsplit_once(')')?
164|        .1
165|        .split_whitespace()
166|        .nth(19)?
167|        .parse()
168|        .ok()
169|}
