{"content":"1|//! Shared-memory projection layer for the projected plugin tree.
2|//!
3|//! The projected plugin tree lives in tmpfs (`/dev/shm/opdbus/state/`).
4|//! The MutationEngine writes one file per plugin on every mutation (atomic
5|//! temp+rename). These helpers read the raw JSON files without a held cache or
6|//! polling, and cooperate through one private service-owned advisory lock
7|//! around data plus manifest access.
8|//!
9|//! This module is the shared contract between the **writer** (op-grpc-bridge
10|//! MutationEngine, the single write door) and the **readers**. The old
11|//! op-projection D-Bus server is deleted. Retired projection paths are never a
12|//! fallback or a source of plugin existence.
13|//!
14|//! General raw state files are service-only (0600). Their location does not
15|//! authorize outward disclosure: wire consumers must apply the exact sealed
16|//! plugin's state-exposure policy. Identity has a separately redacted public
17|//! file (0644) paired transactionally with its protected credential file.
18|
19|use std::fs::{self, OpenOptions};
20|use std::io::Write;
21|use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
22|use std::path::Path;
23|use std::sync::atomic::{AtomicU64, Ordering};
24|
25|#[path = "projection_transactions.rs"]
26|mod transactions;
27|pub use transactions::{
28|    CredentialPublication, PendingCredentialPublication, PendingDocumentPublication,
29|    PrivateDocumentCommit, PrivateDocumentPublication, PrivateProjectionDirectory,
30|    ProjectionCommit, ProjectionSnapshot, commit_identity_projection_durable_in,
31|    pending_identity_publication_in, prepare_projection_directory_in, read_projection_snapshot,
32|    read_projection_snapshot_bounded_in, read_projection_snapshot_in,
33|    recover_identity_projection_in, restrict_projection_file_in, update_projection,
34|    update_projection_in, update_projection_with_credentials_in,
35|};
36|
37|/// Canonical directory for per-plugin present-state files (one JSON file per
38|/// plugin). This is the static tree that `write_projection` maintains and all
39|/// consumers read.
40|pub const SHM_STATE_DIR: &str = "/dev/shm/opdbus/state";
41|/// Private tmpfs directory for local possession credentials. Files here are
42|/// not part of the generic state tree and must never be served by schema
43|/// routing, state sync, snapshots, or web projection readers.
44|pub const SHM_CREDENTIAL_DIR: &str = "/dev/shm/opdbus/credentials";
45|/// Retired path constant retained only for source references. Never read as a
46|/// fallback by the current projection API.
47|pub const SHM_PROJECTION_DIR: &str = "/dev/shm/opdbus/projections";
48|
49|/// Manifest carrying the monotonic `generation` counter. Written LAST as the
50|/// atomic commit point after each projection write. Readers hold a shared lock
51|/// across manifest and data reads and reject an in-progress transaction.
52|pub const SHM_PROJECTION_MANIFEST: &str = "/dev/shm/opdbus/state/.manifest.json";
53|
54|static TEMP_SEQUENCE: AtomicU64 = AtomicU64::new(0);
55|
56|/// The state tree root: the canonical [`SHM_STATE_DIR`] in production.
57|/// `OP_SHM_STATE_DIR` overrides it so tests that drive the MutationEngine
58|/// never write the live projection tree.
59|pub fn shm_state_dir() -> String {
60|    std::env::var("OP_SHM_STATE_DIR").unwrap_or_else(|_| SHM_STATE_DIR.to_string())
61|}
62|
63|/// Atomically publish `bytes` to a `/dev/shm` path via a sibling temp file +
64|/// rename, so readers see either the old or new content, never a torn write.
65|pub fn atomic_write_shm(path: &str, bytes: &[u8]) -> anyhow::Result<()> {
66|    atomic_write_shm_with_permissions(path, bytes, 0o644, None)
67|}
68|
69|/// Atomically publish a sensitive projection with an exact mode and optional
70|/// group owner. Permissions are applied to the sibling temporary file before
71|/// rename, so there is no world-readable interval at the destination.
72|pub fn atomic_write_shm_with_permissions(
73|    path: &str,
74|    bytes: &[u8],
75|    mode: u32,
76|    gid: Option<u32>,
77|) -> anyhow::Result<()> {
78|    let destination = Path::new(path);
79|    let parent = destination
80|        .parent()
81|        .ok_or_else(|| anyhow::anyhow!("Projection path has no parent: {path}"))?;
82|    let filename = destination
83|        .file_name()
84|        .and_then(|value| value.to_str())
85|        .ok_or_else(|| anyhow::anyhow!("Projection path has no UTF-8 filename: {path}"))?;
86|
87|    // A deterministic `<destination>.tmp` races when two mutation tasks
88|    // publish the same plugin concurrently. Use O_EXCL and a process-unique
89|    // sibling name so each writer owns its bytes through the final rename.
90|    let (tmp, mut file) = (0..32)
91|        .find_map(|_| {
92|            let sequence = TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed);
93|            let candidate = parent.join(format!(
94|                ".{filename}.tmp.{}.{}",
95|                std::process::id(),
96|                sequence
97|            ));
98|            match OpenOptions::new()
99|                .write(true)
100|                .create_new(true)
101|                .mode(mode)
102|                .open(&candidate)
103|            {
104|                Ok(file) => Some(Ok((candidate, file))),
105|                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => None,
106|                Err(error) => Some(Err(anyhow::anyhow!(
107|                    "Cannot create {}: {}",
108|                    candidate.display(),
109|                    error
110|                ))),
111|            }
112|        })
113|        .transpose()?
114|        .ok_or_else(|| anyhow::anyhow!("Could not allocate a unique temp file for {path}"))?;
115|
116|    let publish = (|| -> anyhow::Result<()> {
117|        file.set_permissions(fs::Permissions::from_mode(mode))
118|            .map_err(|e| anyhow::anyhow!("Cannot set permissions on {}: {}", tmp.display(), e))?;
119|        file.write_all(bytes)
120|            .map_err(|e| anyhow::anyhow!("Failed to write {}: {}", tmp.display(), e))?;
121|        file.sync_all()
122|            .map_err(|e| anyhow::anyhow!("Failed to sync {}: {}", tmp.display(), e))?;
123|        drop(file);
124|        if let Some(gid) = gid {
125|            nix::unistd::chown(&tmp, None, Some(nix::unistd::Gid::from_raw(gid)))
126|                .map_err(|e| anyhow::anyhow!("Cannot set group on {}: {}", tmp.display(), e))?;
127|        }
128|        fs::rename(&tmp, destination).map_err(|e| {
129|            anyhow::anyhow!(
130|                "Failed to rename {} -> {}: {}",
131|                tmp.display(),
132|                destination.display(),
133|                e
134|            )
135|        })?;
136|        Ok(())
137|    })();
138|    if publish.is_err() {
139|        let _ = fs::remove_file(&tmp);
140|    }
141|    publish
142|}
143|
144|/// Sanitize a plugin id into a safe flat filename (no path separators or NUL).
145|fn safe_filename(plugin_id: &str) -> String {
146|    plugin_id
147|        .chars()
148|        .map(|c| {
149|            if c == '/' || c == '\\' || c == '\0' {
150|                '_'
151|            } else {
152|                c
153|            }
154|        })
155|        .collect()
156|}
157|
158|/// File path for a specific plugin's projection (`<state_dir>/<plugin>.json`).
159|pub fn projection_file_path(plugin_id: &str) -> String {
160|    projection_file_path_in(&shm_state_dir(), plugin_id)
161|}
162|
163|/// File path for a projection under one already-resolved state directory.
164|/// Writers use this form so a process-global test override cannot change
165|/// between resolving the directory and publishing the file.
166|pub fn projection_file_path_in(state_dir: &str, plugin_id: &str) -> String {
167|    format!("{state_dir}/{}.json", safe_filename(plugin_id))
168|}
169|
170|/// Credential directory paired with one already-resolved state tree. Test
171|/// roots keep credentials beneath the same temporary root; production uses a
172|/// separate non-enumerated tmpfs directory.
173|pub fn credential_projection_dir_for_state_dir(state_dir: &str) -> String {
174|    if Path::new(state_dir) == Path::new(SHM_STATE_DIR) {
175|        SHM_CREDENTIAL_DIR.to_string()
176|    } else {
177|        format!("{state_dir}/.credentials")
178|    }
179|}
