{"content":"1|//! Session management using WireGuard pubkey as identity.
2|//!
3|//! Sessions are created when a WireGuard peer connects and
4|//! destroyed on disconnect or timeout.
5|
6|use anyhow::Context;
7|use chrono::{DateTime, Utc};
8|use dashmap::DashMap;
9|use std::sync::Arc;
10|use tokio::sync::Mutex;
11|use tracing::{debug, info, warn};
12|use uuid::Uuid;
13|
14|use crate::gcloud_auth::GCloudAuth;
15|use crate::identity_vault::IdentityVault;
16|#[cfg(test)]
17|use crate::identity_vault::UserRecord;
18|use crate::wireguard::WireGuardIdentity;
19|
20|const SESSION_TIMEOUT_SECS: i64 = 3600; // 1 hour
21|
22|/// Domain-separation context for deriving a deterministic session id from a
23|/// WireGuard pubkey. The same pubkey always yields the same session id, so
24|/// re-authentication after a timeout resumes the same logical session without
25|/// server-side custody of the private key.
26|const SESSION_ID_KDF_CONTEXT: &str = "op-identity session-id v1";
27|
28|/// Server-side proof stored in Cozo; the raw PSK is never persisted.
29|pub fn session_proof(session_id: &str) -> String {
30|    blake3::hash(session_id.as_bytes()).to_hex().to_string()
31|}
32|
33|pub fn verify_session_proof(session_id: &str, stored_proof: &str) -> bool {
34|    session_proof(session_id) == stored_proof
35|}
36|
37|/// Derive a stable session id from a WireGuard pubkey using Blake3 KDF.
38|///
39|/// Output is formatted as a UUID string so existing consumers (headers,
40|/// trace IDs, accountability page) do not need to change. The derivation is
41|/// deterministic and local-only: no network, no DB, no randomness.
42|pub fn derive_session_id(pubkey: &str) -> String {
43|    let key_material = blake3::derive_key(SESSION_ID_KDF_CONTEXT, pubkey.as_bytes());
44|    let bytes: [u8; 16] = key_material[..16]
45|        .try_into()
46|        .expect("16 bytes from 32-byte KDF output");
47|    Uuid::from_bytes(bytes).to_string()
48|}
49|
50|/// Domain-separation context for deriving a deterministic human principal id
51|/// from a WireGuard pubkey. DISTINCT from `SESSION_ID_KDF_CONTEXT`, so a
52|/// human principal id can never collide with a container session id.
53|const PRINCIPAL_ID_KDF_CONTEXT: &str = "op-identity human-principal v1";
54|
55|/// Derive a stable human principal id from a WireGuard pubkey using Blake3
56|/// KDF.
57|///
58|/// Same recipe as [`derive_session_id`] (first 16 bytes of the KDF output as
59|/// a raw UUID, no version/variant munging) but under the distinct
60|/// `PRINCIPAL_ID_KDF_CONTEXT`, separating the two namespaces by construction.
61|/// Deterministic and local-only: no network, no DB, no randomness.
62|pub fn derive_principal_id(pubkey: &str) -> String {
63|    let key_material = blake3::derive_key(PRINCIPAL_ID_KDF_CONTEXT, pubkey.as_bytes());
64|    let bytes: [u8; 16] = key_material[..16]
65|        .try_into()
66|        .expect("16 bytes from 32-byte KDF output");
67|    Uuid::from_bytes(bytes).to_string()
68|}
