70|/// Represents an active session
71|#[derive(Debug, Clone)]
72|pub struct Session {
73|    pub session_id: String,
74|    pub pubkey: String,
75|    pub user_email: Option<String>,
76|    pub oauth_token: Option<String>,
77|    pub token_expires_at: Option<DateTime<Utc>>,
78|    pub created_at: DateTime<Utc>,
79|    pub last_seen_at: DateTime<Utc>,
80|}
81|
82|/// Manages sessions and their lifecycle
83|#[derive(Clone)]
84|pub struct SessionManager {
85|    sessions: Arc<DashMap<String, Session>>,
86|    identity_vault: Arc<Mutex<IdentityVault>>,
87|    gcloud_auth: GCloudAuth,
88|    wireguard: WireGuardIdentity,
89|    current_session_id: Arc<Mutex<Option<String>>>,
90|}
91|
92|impl SessionManager {
93|    pub fn new() -> anyhow::Result<Self> {
94|        Self::with_vault_path(crate::identity_vault::DEFAULT_VAULT_PATH)
95|    }
96|
97|    /// Backward-compatible constructor for explicit interface-based identity wiring.
98|    ///
99|    /// Deprecated: WG-interface-based identity is deprecated in favor of explicit
100|    /// pubkey injection (WG_PUBKEY / signed metadata).
101|    pub fn with_wireguard_interface(interface: &str) -> anyhow::Result<Self> {
102|        Self::with_vault_and_interface(crate::identity_vault::DEFAULT_VAULT_PATH, interface)
103|    }
104|
105|    pub fn with_vault_path<P: AsRef<std::path::Path>>(path: P) -> anyhow::Result<Self> {
106|        // Keeping this overload for compatibility, but do not assume a WG interface.
107|        // WG interface defaults are deprecated; identity should be injected via pubkey.
108|        Self::with_vault_and_interface(path, "")
109|    }
110|
111|    pub fn with_vault_and_interface<P: AsRef<std::path::Path>>(
112|        path: P,
113|        interface: &str,
114|    ) -> anyhow::Result<Self> {
115|        // SQL is obsolete in the 3tched architecture.
116|        // We use in-memory DashMaps to prevent Btrfs mutation loops; the vault
117|        // is the only persistent record and is stored under /etc/ghostbridge.
118|        let path = path.as_ref().to_path_buf();
119|        // An unreadable or corrupt identity authority must fail closed. Treating
120|        // it as an empty vault can silently discard account mappings and allow
121|        // later writes to replace the only durable identity record.
122|        let vault = IdentityVault::load_from(&path)
123|            .with_context(|| format!("load identity vault from {}", path.display()))?;
124|        Ok(Self {
125|            sessions: Arc::new(DashMap::new()),
126|            identity_vault: Arc::new(Mutex::new(vault)),
127|            gcloud_auth: GCloudAuth::new(),
128|            wireguard: WireGuardIdentity::with_interface(interface),
129|            current_session_id: Arc::new(Mutex::new(None)),
130|        })
131|    }
132|
133|    /// Get the GCloud auth provider
134|    pub fn gcloud_auth(&self) -> &GCloudAuth {
135|        &self.gcloud_auth
136|    }
137|
138|    /// Get the WireGuard identity provider
139|    pub fn wireguard(&self) -> &WireGuardIdentity {
140|        &self.wireguard
141|    }
142|
143|    /// Create or retrieve session based on WireGuard identity
144|    pub async fn get_or_create_session_from_wireguard(&self) -> anyhow::Result<Session> {
145|        let pubkey = self.wireguard.get_local_pubkey()?;
146|        self.get_or_create_session(&pubkey).await
147|    }
148|
149|    /// Get or create a session for a given pubkey
150|    pub async fn get_or_create_session(&self, pubkey: &str) -> anyhow::Result<Session> {
151|        let now = Utc::now();
152|
153|        // Check for existing valid session
154|        if let Some(mut session_ref) = self.sessions.iter_mut().find(|r| {
155|            r.pubkey == pubkey && (now - r.last_seen_at).num_seconds() < SESSION_TIMEOUT_SECS
156|        }) {
157|            debug!("Found existing session: {}", session_ref.session_id);
158|            session_ref.last_seen_at = now;
159|            let session = session_ref.clone();
160|
161|            *self.current_session_id.lock().await = Some(session.session_id.clone());
162|            return Ok(session);
163|        }
164|
165|        // Create new session from the derived key for this pubkey.
166|        // The same pubkey always yields the same session id, so re-provisioning
167|        // the same machine resumes the same logical session without server-side
168|        // custody of the private key.
169|        let session_id = derive_session_id(pubkey);
170|        info!(
171|            "Creating new derived session: {} for pubkey: {}",
172|            session_id, pubkey
173|        );
174|
175|        // Try to get user email from the persistent identity vault.
176|        let user_email = self
177|            .identity_vault
178|            .lock()
179|            .await
180|            .get(pubkey)
181|            .map(|u| u.user_email.clone());
182|
183|        // Try to get OAuth token
184|        let (oauth_token, token_expires_at) = match self.gcloud_auth.get_token().await {
185|            Ok((token, expires)) => (Some(token), Some(expires)),
186|            Err(e) => {
187|                warn!("Could not get OAuth token: {}", e);
188|                (None, None)
189|            }
190|        };
191|
192|        let session = Session {
193|            session_id: session_id.clone(),
194|            pubkey: pubkey.to_string(),
195|            user_email,
196|            oauth_token,
197|            token_expires_at,
198|            created_at: now,
199|            last_seen_at: now,
200|        };","total_lines":469,"file_size":17348,"truncated":true,"hint":"Use offset=201 to continue reading (showing 1-200 of 469 lines)","is_binary":false,"is_image":false,"not_found":false}

