282|pub(super) async fn admit(
283|    engine: &MutationEngine,
284|    store: &IdentitySledStore,
285|    actor: &str,
286|    actor_session_id: &str,
287|    actor_genesis: &str,
288|    original: &ProvisionSealPin,
289|) -> Result<()> {
290|    crate::method_contract_admission::admit_compiled_method(
291|        "identity_sled",
292|        &original.method,
293|        Some(PROVISION_CAPABILITY),
294|    )?;
295|    let current = strict_identity_contract()?;
296|    anyhow::ensure!(
297|        current.schema_hash == original.schema_hash
298|            && current.blob.manifest == original.blob.manifest
299|            && current.blob.schema_json == original.blob.schema_json
300|            && current.blob.descriptor_set == original.blob.descriptor_set
301|            && current.blob.meta_json == original.blob.meta_json,
302|        "seed provision seal changed while queued"
303|    );
304|    anyhow::ensure!(
305|        crate::interceptor::load_capability_grants(actor).contains(PROVISION_CAPABILITY),
306|        "seed provision requires a current exact-principal grant"
307|    );
308|    let current = engine
309|        .session_context_for_actor(actor)
310|        .await
311|        .context("provisioning caller has no current authenticated session context")?;
312|    anyhow::ensure!(
313|        current.session_id == actor_session_id && current.genesis_hex == actor_genesis,
314|        "provisioning caller session changed while queued"
315|    );
316|    let revision = load_revision(store, actor_session_id).await?;
317|    let sled = revision_sled(&revision)?.context("provisioning caller identity disappeared")?;
318|    // Humans have no per-account container (not scalable); their liveness is
319|    // already proven above by the live session/genesis match. The stored-SID1
320|    // self-instance check only makes sense for a principal that owns a
321|    // container, so it stays scoped to non-human actors.
322|    if sled.principal_kind.as_deref() != Some("human") {
323|        super::root_repair::verify_current_repair_sid1(engine, &sled, actor, actor_genesis).await?;
324|    }
325|    Ok(())
