1841|/// The JSON document is keyed by exact `principal_id` plus `$` group entries.
1842|/// A principal inherits every capability of the groups named in its `groups`
1843|/// array, then its own `capabilities`. Missing, malformed, or unreadable grant
1844|/// state fails closed.
1845|pub fn load_capability_grants(principal_id: &str) -> std::collections::HashSet<String> {
1846|    let path = std::env::var("OP_GRANTS_PATH")
1847|        .unwrap_or_else(|_| "/dev/shm/opdbus/capability-grants.json".to_string());
1848|    let Ok(bytes) = std::fs::read(path) else {
1849|        return std::collections::HashSet::new();
1850|    };
1851|    let Ok(document) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
1852|        return std::collections::HashSet::new();
1853|    };
1854|    capabilities_for_principal(&document, principal_id)
1855|}
1856|
1857|/// Parse one principal's grants from a document of principals and groups.
1858|///
1859|/// The complete document must pass the same validation used by the grant
1860|/// materializer. Looking up a group name returns nothing: groups are not callers.
1861|pub(crate) fn capabilities_for_principal(
1862|    document: &serde_json::Value,
1863|    principal_id: &str,
1864|) -> std::collections::HashSet<String> {
1865|    if principal_id.is_empty() || principal_id == "*" || principal_id.starts_with('$') {
1866|        return std::collections::HashSet::new();
1867|    }
1868|    let Ok(entries) = validated_grant_entries(document) else {
1869|        return std::collections::HashSet::new();
1870|    };
1871|    let Some(entry) = entries.get(principal_id) else {
1872|        return std::collections::HashSet::new();
1873|    };
1874|    let mut granted = std::collections::HashSet::new();
1875|    let Some(own) = entry.get("capabilities").and_then(serde_json::Value::as_array) else {
1876|        return std::collections::HashSet::new();
1877|    };
1878|    granted.extend(own.iter().filter_map(serde_json::Value::as_str).map(str::to_string));
1879|    let Some(groups) = entry.get("groups") else {
1880|        return granted;
1881|    };
1882|    let Some(groups) = groups.as_array() else {
1883|        return std::collections::HashSet::new();
1884|    };
1885|    for group in groups {
1886|        let Some(name) = group.as_str() else {
