178|/// Anchor a human session after the interceptor has already verified the
179|/// decoy assertion. The sled store stays on the engine; this policy does not.
180|pub(crate) async fn anchor_verified_human_session(
181|    engine: &MutationEngine,
182|    wireguard_pubkey: &str,
183|) -> Option<crate::mutation_engine::SessionContext> {
184|    let valid_wireguard_key = base64::Engine::decode(
185|        &base64::engine::general_purpose::STANDARD,
186|        wireguard_pubkey.trim(),
187|    )
188|    .is_ok_and(|raw| raw.len() == 32);
189|    if !valid_wireguard_key {
190|        return None;
191|    }
192|    let session_id = op_identity::session::derive_session_id(wireguard_pubkey);
193|    // Unavailable or malformed committed identity state must not be treated
194|    // as a first arrival eligible for minting.
195|    let record = crate::identity_sled_dispatch::stored_session(engine, &session_id)
196|        .await
197|        .ok()?;
198|    if let Some(record) = record {
199|        let now = chrono::Utc::now().timestamp();
200|        let current = record.is_anchored()
201|            && record.wireguard_pubkey == wireguard_pubkey
202|            && record
203|                .expires_at
204|                .is_none_or(|expires_at| expires_at == 0 || expires_at > now);
205|        if !current {
206|            tracing::warn!(
207|                %session_id,
208|                "verified identity has an expired or mismatched authoritative sled"
209|            );
210|            return None;
211|        }
212|        crate::identity_sled_dispatch::set_session_actor_class(engine, &session_id, "human")
213|            .await
214|            .ok()?;
215|        let context = crate::mutation_engine::SessionContext {
216|            genesis_hex: record.genesis.unwrap_or_default(),
217|            session_id: record.session_id,
218|            wireguard_pubkey: record.wireguard_pubkey,
219|            sealed_id_digest: crate::mutation_engine::sealed_id_digest(record.sealed_id.as_deref()),
220|        };
221|        engine.register_session_context(context.clone()).await;
222|        return Some(context);
223|    }
224|    match engine
225|        .mint_and_store_genesis(&session_id, wireguard_pubkey)
226|        .await
227|    {
228|        Ok(_) => {
229|            crate::identity_sled_dispatch::set_session_actor_class(engine, &session_id, "human")
230|                .await
231|                .ok()?;
232|            engine.session_context(&session_id).await
233|        }
234|        Err(error) => {
235|            tracing::warn!(
236|                %error,
237|                %session_id,
238|                "verified human arrival could not be anchored"
239|            );
240|            None
241|        }
242|    }
